/// A post-flight retrospective capturing what worked, what failed, and lessons learned.
/// Generated by AI after a flight completes, used to improve future flight planning.
#[derive(Debug, Clone, Serialize, serde::Deserialize)]
pub struct FlightRetrospective {
    pub id: String,
    pub flight_id: String,
    pub flight_title: String,
    pub summary: String,
    #[serde(default)]
    pub what_worked: Vec<String>,
    #[serde(default)]
    pub what_failed: Vec<String>,
    #[serde(default)]
    pub lessons_learned: Vec<String>,
    #[serde(default)]
    pub suggested_improvements: Vec<String>,
    #[serde(default)]
    pub tags: Vec<String>,
    pub created_at: u64,
}

/// A saved SSH server connection configuration.
#[derive(Debug, Clone, Serialize, serde::Deserialize)]
pub struct ServerConfig {
    pub id: String,
    pub name: String,
    pub host: String,
    #[serde(default = "default_ssh_port")]
    pub port: u16,
    pub username: String,
    pub auth_method: String, // "agent" | "key" | "password"
    #[serde(default)]
    pub key_path: Option<String>,
    #[serde(default)]
    pub remote_path: Option<String>,
    #[serde(default)]
    pub last_connected_at: Option<u64>,
    #[serde(default)]
    pub installed_agents: Vec<String>,
    /// SHA256 fingerprint of the host key captured at first-connect.
    /// `None` for legacy entries — those connect via TOFU fallback until
    /// the user re-saves the server to pin the key.
    #[serde(default)]
    pub host_fingerprint: Option<String>,
}

fn default_ssh_port() -> u16 {
    22
}

/// A named CLI login, identified purely by the config directory the CLI is
/// pointed at (`CLAUDE_CONFIG_DIR` for claude-code, `CODEX_HOME` for codex).
///
/// **No secrets live here.** The record is a pointer: credentials, settings,
/// MCP config, and session history all live inside `config_dir` where the CLI
/// itself writes them. Deleting a record therefore never deletes a login —
/// the directory on disk is left untouched.
///
/// Absence of a selected account means "ambient login" (the CLI's own default
/// `~/.claude` / `~/.codex`), which is the pre-multi-account behaviour.
#[derive(Debug, Clone, Serialize, serde::Deserialize)]
pub struct CliAccount {
    pub id: String,
    pub label: String,
    /// "claude-code" | "codex" — kept as a string for the same
    /// forward-compatibility reason `ServerConfig::auth_method` is.
    pub cli: String,
    pub config_dir: String,
    /// Display only. NEVER used for authentication or account matching.
    #[serde(default)]
    pub email: Option<String>,
    pub created_at: u64,
    #[serde(default)]
    pub last_used_at: Option<u64>,
}

pub const STATE_FILENAME: &str = "state.v1.json";
const PROVIDER_SETTINGS_FILENAME: &str = "provider-settings.v1.json";
pub const DEFAULT_OLLAMA_ROOT_BASE_URL: &str = "http://localhost:11434";

/// MiniMax's documented **global** OpenAI-compatible host. Mainland-China
/// accounts are served from `https://api.minimaxi.com/v1` instead, which is why
/// this is overridable. (The historical `api.minimaxi.chat` host this app used
/// to hardcode appears nowhere in MiniMax's current docs.)
pub const DEFAULT_MINIMAX_BASE_URL: &str = "https://api.minimax.io/v1";

static STATE_LOCK: Mutex<()> = Mutex::new(());
static PROVIDER_SETTINGS_LOCK: Mutex<()> = Mutex::new(());

/// Async-safe critical-section mutex for every state writer. Callers hold it
/// across the **entire** load → mutate → save sequence, so a stale full-state
/// save cannot overwrite a slice save that landed between the load and the
/// save.
///
/// Every writer reachable from a live IPC command acquires this gate
/// **asynchronously** — [`with_state_lock`], [`update_state_async`], and the
/// `save_*` slice writers — which is fair FIFO. The two remaining synchronous
/// writers ([`save_state`], [`update_state`]) run only at startup, before the
/// runtime serves IPC, and go through [`lock_state_gate_blocking`].
///
/// State writers must acquire this gate before `STATE_LOCK`; do not invert
/// that order.
static ASYNC_STATE_LOCK: AsyncMutex<()> = AsyncMutex::const_new(());

#[derive(Debug, Clone, Serialize, serde::Deserialize, Default)]
struct ProviderRuntimeSettings {
    #[serde(default)]
    ollama_base_url: Option<String>,
    #[serde(default)]
    minimax_base_url: Option<String>,
    /// Ceiling for the `num_ctx` Ollama is asked to allocate. `None` = the
    /// built-in default in `core::llm_ollama`. See that module for why this is
    /// a cap rather than an absolute value.
    #[serde(default)]
    ollama_num_ctx_cap: Option<u32>,
    /// How long Ollama keeps a model resident after a turn (`30m`, `-1`, …).
    #[serde(default)]
    ollama_keep_alive: Option<String>,
    /// LM2 — user-supplied OpenAI-compatible endpoint (vLLM / LM Studio /
    /// LiteLLM / Together, …). Stored INCLUDING any path prefix (typically
    /// `/v1`) and used verbatim as `{base}/chat/completions` — unlike the
    /// Ollama URL, whose `/v1` is stripped because the native routes live at
    /// the root. There is no default: unset means the provider is
    /// unconfigured.
    #[serde(default)]
    custom_compat_base_url: Option<String>,
    /// Manual model list for the custom endpoint — there is no reliable
    /// discovery route across OpenAI-compatible servers, so the user
    /// maintains the list in Settings.
    #[serde(default)]
    custom_compat_models: Option<Vec<String>>,
    #[serde(default)]
    named_provider_base_urls: std::collections::HashMap<String, String>,
}

#[derive(Debug, Clone, Serialize, serde::Deserialize, Default)]
pub struct PersistedUiState {
    pub selected_flight_id: Option<String>,
    pub selected_view: Option<String>,
    pub theme: Option<String>,
    /// IANA zone name (e.g. `America/New_York`). `None` means follow the host
    /// system zone, which is also the default for an install that predates this
    /// field. Stored as the zone *name*, never a fixed offset: an offset is
    /// wrong for half the year wherever DST applies.
    pub time_zone: Option<String>,
}

#[derive(Debug, Clone, Serialize, serde::Deserialize)]
pub struct PersistedState {
    pub version: u32,
    pub flights: Vec<Flight>,
    pub agents: Vec<AgentConfig>,
    pub settings: OrchestratorSettings,
    pub ui: PersistedUiState,
    #[serde(default)]
    pub issues: Vec<Issue>,
    #[serde(default)]
    pub workspaces: Vec<Workspace>,
    #[serde(default)]
    pub retrospectives: Vec<FlightRetrospective>,
    #[serde(default)]
    pub memory_events: Vec<serde_json::Value>,
    #[serde(default)]
    pub memory_patterns: Vec<serde_json::Value>,
    #[serde(default)]
    pub servers: Vec<ServerConfig>,
    /// Named per-CLI logins (multi-account support for PTY/CLI sessions).
    #[serde(default)]
    pub cli_accounts: Vec<CliAccount>,
    /// Sticky per-project account choice: `project path -> cli -> account id`.
    /// `BTreeMap` (not `HashMap`) so the on-disk JSON has a stable key order
    /// and repeated saves do not churn the file.
    #[serde(default)]
    pub cli_account_defaults: BTreeMap<String, BTreeMap<String, String>>,
    /// Legacy autonomous-Planner approval records. Read-compatible only.
    #[serde(default)]
    pub flight_approvals: Vec<FlightApprovalRequest>,
    /// One-time marker: ISO timestamp at which `core::reprice` rewrote the
    /// historical cost figures that were computed with the pre-CE2 (wrong)
    /// model rates. `None` means the pass has not run on this install.
    ///
    /// This is only a fast-path skip so a mature ledger isn't rescanned on
    /// every launch — the migration is *also* idempotent per record (each
    /// rewritten record carries its own `repriced_at` / `repricedAt` marker),
    /// so losing this flag cannot cause a double-apply.
    #[serde(default)]
    pub cost_reprice_v1_at: Option<String>,
}

impl Default for PersistedState {
    fn default() -> Self {
        Self {
            version: 1,
            flights: Vec::new(),
            agents: Vec::new(),
            settings: OrchestratorSettings::default(),
            ui: PersistedUiState::default(),
            issues: Vec::new(),
            workspaces: Vec::new(),
            retrospectives: Vec::new(),
            memory_events: Vec::new(),
            memory_patterns: Vec::new(),
            servers: Vec::new(),
            cli_accounts: Vec::new(),
            cli_account_defaults: BTreeMap::new(),
            flight_approvals: Vec::new(),
            cost_reprice_v1_at: None,
        }
    }
}

// ---------------------------------------------------------------------------
// Test-only data-dir redirection.
//
// The real storage writers (`with_state_lock`, `accumulate_*_cost`, the
// `save_*` slice writers) all resolve their target through `data_dir()`, which
// is hardcoded to `~/.packetbench`. To exercise those writers HERMETICALLY in
// the default `cargo test` pass — without the historic `#[ignore]`+`HOME`
// rewrite that clobbered real user state — tests carry a PER-THREAD override
// that redirects `data_dir()` at a tempdir. It is thread-local (not a global /
// env-var mutation) so parallel tests each get their own isolated directory
// and never race one another. The whole facility is `#[cfg(test)]`, so the
// production `data_dir()` below compiles byte-identically in release builds.
// ---------------------------------------------------------------------------

#[cfg(test)]
thread_local! {
    static TEST_DATA_DIR: std::cell::RefCell<Option<PathBuf>> =
        const { std::cell::RefCell::new(None) };
}

/// Test-only RAII guard: redirects [`data_dir`] to a tempdir on the current
/// thread and restores the previous value on drop (including on panic).
#[cfg(test)]
pub(crate) struct TestDataDirGuard {
    prev: Option<PathBuf>,
}

#[cfg(test)]
impl Drop for TestDataDirGuard {
    fn drop(&mut self) {
        let prev = self.prev.take();
        TEST_DATA_DIR.with(|c| *c.borrow_mut() = prev);
    }
}

/// Test-only: point `data_dir()` at `dir` for the current thread until the
/// returned guard drops. Because `#[tokio::test]` drives futures on a
/// current-thread runtime, the override stays live across the async storage
/// writers' `.await` points (all polled on the one thread that set it).
#[cfg(test)]
pub(crate) fn redirect_data_dir_for_test(dir: impl Into<PathBuf>) -> TestDataDirGuard {
    let prev = TEST_DATA_DIR.with(|c| c.borrow_mut().replace(dir.into()));
    TestDataDirGuard { prev }
}

/// Get the PacketBench data directory (~/.packetbench/).
///
/// Resolves the SAME directory for both reads and writes so a failed startup
/// migration can't strand the user on an empty new dir while their data sits
/// in the legacy dir:
/// - prefer the new dir if it already exists,
/// - otherwise fall back to the legacy dir if it exists AND is recognizably
///   ours (the sibling `packetcode` TUI owns that path on fresh machines),
/// - otherwise return the new dir (fresh install).
pub fn data_dir() -> PathBuf {
    #[cfg(test)]
    if let Some(dir) = TEST_DATA_DIR.with(|c| c.borrow().clone()) {
        return dir;
    }
    let home = home_dir().unwrap_or_else(|| ".".to_string());
    resolve_data_dir(Path::new(&home))
}

/// Body of [`data_dir`], parameterized on the home directory so the
/// legacy-fallback rule is testable without touching process-wide env vars.
fn resolve_data_dir(home: &Path) -> PathBuf {
    let new_dir = home.join(crate::core::brand::DATA_DIR_NAME);
    if new_dir.exists() {
        return new_dir;
    }
    // Only adopt `~/.packetcode` when it is OUR pre-rename dir. The sibling
    // `packetcode` TUI claimed that path as its own home after the rename, and
    // writing our state into it would scribble on another product's data.
    let legacy_dir = home.join(crate::core::brand::LEGACY_DATA_DIR_NAME);
    if crate::core::migration::classify_legacy_dir(&legacy_dir)
        == crate::core::migration::LegacyDirShape::Ours
    {
        return legacy_dir;
    }
    new_dir
}

/// Ensure the data directory exists.
pub fn ensure_data_dir() -> Result<PathBuf, String> {
    let dir = data_dir();
    if !dir.exists() {
        fs::create_dir_all(&dir)
            .map_err(|e| format!("Failed to create data dir {:?}: {}", dir, e))?;
        info!(
            "Created {} data dir: {:?}",
            crate::core::brand::APP_NAME,
            dir
        );
    }
    Ok(dir)
}

/// Derive the sibling `.bak` path for a primary file, matching the exact
/// extension-mangling that `write_with_backup` uses (`<ext>.bak`).
fn backup_path_for(path: &Path) -> PathBuf {
    path.with_extension(format!(
        "{}.bak",
        path.extension()
            .and_then(|ext| ext.to_str())
            .unwrap_or("json")
    ))
}

/// Derive the sibling `.tmp` path for a primary file, matching the exact
/// extension-mangling that `write_with_backup` uses (`<ext>.tmp`). A `.tmp`
/// may survive on disk if a crash hit between the fsync and the rename-in.
fn tmp_path_for(path: &Path) -> PathBuf {
    path.with_extension(format!(
        "{}.tmp",
        path.extension()
            .and_then(|ext| ext.to_str())
            .unwrap_or("json")
    ))
}

/// Quarantine a corrupt primary file by renaming it out of the way BEFORE any
/// recovery or save runs. This is mandatory: if the corrupt primary stays in
/// place, the next `write_with_backup` would copy it into `.bak` and destroy
/// the last good backup. After a successful rename `path.exists()` is false,
/// so the backup step is skipped and the good `.bak` survives. Best-effort:
/// on failure (e.g. a Windows sharing violation) we warn and continue rather
/// than panic or block startup, mirroring the migration warn-and-continue style.
fn quarantine_corrupt(path: &Path) {
    let ts = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    let quarantine = path.with_extension(format!(
        "{}.corrupt-{}",
        path.extension()
            .and_then(|ext| ext.to_str())
            .unwrap_or("json"),
        ts
    ));
    match fs::rename(path, &quarantine) {
        Ok(()) => warn!(
            "Quarantined corrupt {:?} -> {:?}; attempting recovery",
            path, quarantine
        ),
        Err(e) => warn!(
            "Failed to quarantine corrupt {:?}: {} — continuing recovery",
            path, e
        ),
    }
}

/// Read + parse a sibling file (`.bak` or `.tmp`) as `T`. Returns `Some` only
/// on a clean parse; any read or parse error yields `None` (the ladder simply
/// falls through to the next candidate).
fn try_recover<T: serde::de::DeserializeOwned>(path: &Path) -> Option<T> {
    let content = fs::read_to_string(path).ok()?;
    serde_json::from_str::<T>(&content).ok()
}

pub fn load_state() -> PersistedState {
    load_state_from(&data_dir())
}

/// Recovery ladder over a specific data directory. `load_state` is a thin
/// wrapper that resolves `data_dir()` and delegates here; splitting the
/// directory out keeps the ladder testable with an injected tempdir without
/// changing any runtime behavior.
fn load_state_from(dir: &Path) -> PersistedState {
    let path = dir.join(STATE_FILENAME);

    // 1. Primary: clean read+parse wins immediately.
    match fs::read_to_string(&path) {
        Ok(content) => match serde_json::from_str::<PersistedState>(&content) {
            Ok(state) => return state,
            Err(e) => {
                // 2. Primary parsed-but-corrupt: quarantine FIRST (before any
                // recovery/return) so the next save can't clobber the good .bak.
                warn!("Failed to parse {:?}: {}, attempting recovery", path, e);
                quarantine_corrupt(&path);
            }
        },
        Err(_) => {
            // File-missing: fall through to .bak/.tmp. Genuine first run (no
            // primary, no .bak, no .tmp) stays fast and silent → default.
        }
    }

    // Recovery is intentionally READ-ONLY. `load_state` is called from many
    // sites that do NOT hold STATE_LOCK (get_state, git, flight_attempts,
    // orchestration, worktree, …); re-persisting here would issue an unlocked
    // `write_with_backup` that can race a locked writer on the shared `.tmp`
    // and land a stale snapshot over fresh state — a lost update. We return the
    // recovered value and let the next lock-held save reconcile the primary
    // (the locked writer's own internal `load_state` returns the same recovered
    // value and writes it back properly under STATE_LOCK).

    // 3. Backup sibling (.bak).
    let backup_path = backup_path_for(&path);
    if let Some(state) = try_recover::<PersistedState>(&backup_path) {
        warn!("Recovered state from backup {:?}", backup_path);
        return state;
    }

    // 4. Orphaned tmp (.tmp) — a complete fsynced write that never renamed in.
    let tmp_path = tmp_path_for(&path);
    if let Some(state) = try_recover::<PersistedState>(&tmp_path) {
        warn!("Recovered state from orphaned tmp {:?}", tmp_path);
        return state;
    }

    // 5. Nothing recoverable → default.
    PersistedState::default()
}

fn save_state_inner(state: &PersistedState) -> Result<(), String> {
    let dir = ensure_data_dir()?;
    let path = dir.join(STATE_FILENAME);
    let json = serde_json::to_string_pretty(state)
        .map_err(|e| format!("Failed to serialize persisted state: {}", e))?;
    write_with_backup(&path, &json)?;
    Ok(())
}

/// Blocking, **fair** acquire of the shared state gate.
///
/// Reserved for the synchronous writers that run before the Tauri async
/// runtime serves IPC (startup migration, cost reprice, flight recovery) and
/// for `#[test]` code. `blocking_lock` joins the same FIFO wait queue as
/// `lock().await`.
///
/// This used to spin on `try_lock` with a 1 ms sleep. `try_lock` bypasses the
/// queue and fails while *any* `.lock().await` waiter is parked, so a
/// spinning caller on the IPC thread could lose indefinitely against a bursty
/// async writer (e.g. the per-`turn_summary` cost rollup) — 100% of a core, a
/// frozen UI, no timeout and no error. Every writer that can run while the app
/// is live now takes the async path instead: [`update_state_async`],
/// [`with_state_lock`], and the `save_*` slice writers.
///
/// # Panics
/// Tokio panics if this is called from inside a runtime context. That is the
/// intended guard rail — an IPC-serving writer must not reach this function.
fn lock_state_gate_blocking() -> tokio::sync::MutexGuard<'static, ()> {
    ASYNC_STATE_LOCK.blocking_lock()
}

/// Acquire `STATE_LOCK`, recovering from poisoning rather than failing
/// forever.
///
/// The guarded value is `()`, so a panic while the lock was held cannot have
/// left anything half-written — `save_state_inner` persists atomically via
/// `write_with_backup`. Returning `Err("Lock poisoned")` (what this replaced)
/// made *every* subsequent save fail for the remaining process lifetime, and
/// most call sites discard the error (`let _ = …` in `flight_attempts` /
/// `api_agent`), so the user silently lost all persistence from the first
/// panic onward.
fn lock_state_mutex() -> std::sync::MutexGuard<'static, ()> {
    STATE_LOCK.lock().unwrap_or_else(|e| e.into_inner())
}

/// Same poisoned-lock recovery as [`lock_state_mutex`], for the provider
/// runtime-settings file.
fn lock_provider_settings_mutex() -> std::sync::MutexGuard<'static, ()> {
    PROVIDER_SETTINGS_LOCK
        .lock()
        .unwrap_or_else(|e| e.into_inner())
}

/// Load → mutate → save under `STATE_LOCK`. The caller **must** already hold
/// the async state gate (`ASYNC_STATE_LOCK`); the two public wrappers below
/// are the only intended entry points.
fn update_state_locked<F, R>(mutate: F) -> Result<R, String>
where
    F: FnOnce(&mut PersistedState) -> R,
{
    let _lock = lock_state_mutex();
    let mut state = load_state();
    let result = mutate(&mut state);
    state.version += 1;
    save_state_inner(&state)?;
    Ok(result)
}

pub fn save_state(state: &PersistedState) -> Result<(), String> {
    let _async_lock = lock_state_gate_blocking();
    let _lock = lock_state_mutex();
    let mut state = state.clone();
    state.version += 1;
    save_state_inner(&state)
}

/// Atomic load → mutate → save under `STATE_LOCK`. Mirrors the slice-writer
/// pattern (e.g. `save_flights`) for callers that need to merge multiple
/// fields into the persisted state in a single critical section, instead of
/// `load_state(); mutate; save_state()` — which exposes a lost-update race
/// against concurrent slice writers landing between the load and the save.
///
/// **Synchronous, and therefore startup-only.** It blocks the calling thread
/// on the state gate (see [`lock_state_gate_blocking`]) and panics if a Tokio
/// runtime is active on that thread. Anything reachable from an IPC command
/// must use [`update_state_async`].
pub fn update_state<F, R>(mutate: F) -> Result<R, String>
where
    F: FnOnce(&mut PersistedState) -> R,
{
    let _async_lock = lock_state_gate_blocking();
    update_state_locked(mutate)
}

/// Async twin of [`update_state`], and the entry point every slice writer
/// below routes through. Awaits the state gate fairly instead of blocking a
/// thread on it, so an IPC command can never starve behind async writers.
///
/// Like [`with_state_lock`], the gate is held across the whole critical
/// section — callers MUST NOT re-enter any state writer from inside `mutate`.
pub async fn update_state_async<F, R>(mutate: F) -> Result<R, String>
where
    F: FnOnce(&mut PersistedState) -> R,
{
    let _async_lock = ASYNC_STATE_LOCK.lock().await;
    update_state_locked(mutate)
}

/// Run an async closure with an exclusive load → mutate → save critical
/// section over `PersistedState`. Solves the lost-update race that
/// `load_state(); mutate; save_state()` exposes when called from
/// concurrent async contexts (attempt status, executor cost, etc.).
///
/// Contract:
///   * The closure receives a `&mut PersistedState` already loaded under
///     the mutex.
///   * If the closure returns `Ok(R)`, the state is persisted under the
///     same lock and `R` is returned to the caller.
///   * If the closure returns `Err`, the state is **not** persisted — the
///     mutex is released and the error is propagated unchanged.
///   * The mutex is held across the closure's `.await` points, so callers
///     MUST NOT re-enter `with_state_lock` from within their closure
///     (doing so will deadlock). The same applies to *any* other state
///     writer: `update_state_async` awaits the same gate and would deadlock,
///     and the synchronous `update_state` / `save_state` would livelock the
///     thread on a gate this task will never release. No call site does this
///     today; keep it that way.
///   * Tokio `Mutex` is fair-ish and not cancellation-safe at the lock
///     acquire site — callers that need to abort should drop the future
///     *before* it acquires the lock.
///
/// Sync state writers in this module acquire the same gate before taking
/// `STATE_LOCK`, so this helper is serialized against both async planner
/// writers and sync slice writers.
pub async fn with_state_lock<F, Fut, R>(action: F) -> Result<R, String>
where
    F: FnOnce(&mut PersistedState) -> Fut,
    Fut: Future<Output = Result<R, String>>,
{
    let _guard = ASYNC_STATE_LOCK.lock().await;
    let mut state = load_state();
    let result = action(&mut state).await?;
    let _lock = lock_state_mutex();
    state.version += 1;
    save_state_inner(&state)?;
    Ok(result)
}

fn merge_attempts_for_frontend_save(existing: &[Attempt], incoming: Vec<Attempt>) -> Vec<Attempt> {
    let mut merged = Vec::with_capacity(existing.len().max(incoming.len()));

    for candidate in incoming {
        if let Some(current) = existing.iter().find(|attempt| attempt.id == candidate.id) {
            // Attempt lifecycle is backend-owned. A whole-slice frontend save
            // may carry a stale status while Rust is processing done/error or
            // cleanup. Keep the authoritative record, accepting only the
            // frontend's independently-derived usage counters and error text.
            //
            // `review_gate` is part of that authoritative record and is
            // deliberately NOT copied from `candidate`: the Reviewer Gate
            // verdict gates acceptance in `update_attempt_status`, so it is
            // written by `set_attempt_review_gate` under the state lock, not
            // smuggled in on a whole-slice save that may be arbitrarily stale.
            let mut attempt = current.clone();
            attempt.tokens = attempt.tokens.max(candidate.tokens);
            attempt.cost = attempt.cost.max(candidate.cost);
            if attempt.error_message.is_none() {
                attempt.error_message = candidate.error_message;
            }
            if attempt.completed_at.is_none() {
                attempt.completed_at = candidate.completed_at;
            }
            if attempt.draft_pr_number.is_none() {
                attempt.draft_pr_number = candidate.draft_pr_number;
            }
            merged.push(attempt);
        } else {
            merged.push(candidate);
        }
    }

    // A stale frontend snapshot can predate an Attempt that Rust just
    // appended. Never delete such an Attempt merely because it is absent from
    // the incoming whole-slice save.
    for current in existing {
        if !merged.iter().any(|attempt| attempt.id == current.id) {
            merged.push(current.clone());
        }
    }

    merged
}

fn merge_flights_for_frontend_save(existing: &[Flight], incoming: Vec<Flight>) -> Vec<Flight> {
    incoming
        .into_iter()
        .map(|mut candidate| {
            let Some(current) = existing.iter().find(|flight| flight.id == candidate.id) else {
                return candidate;
            };

            candidate.attempts =
                merge_attempts_for_frontend_save(&current.attempts, candidate.attempts);
            candidate.total_tokens = candidate.total_tokens.max(current.total_tokens);
            candidate.total_cost = candidate.total_cost.max(current.total_cost);
            candidate.updated_at = candidate.updated_at.max(current.updated_at);
            if candidate.prompt.is_none() {
                candidate.prompt = current.prompt.clone();
            }
            if candidate.planning_conversation_id.is_none() {
                candidate.planning_conversation_id = current.planning_conversation_id.clone();
            }

            // These fields are retained only for lossless loading of legacy
            // Flight Planner state. A current frontend snapshot must not erase
            // them simply because no live UI reads or writes them anymore.
            if candidate.planner_session_id.is_none() {
                candidate.planner_session_id = current.planner_session_id.clone();
            }
            if candidate.planner_status.is_none() {
                candidate.planner_status = current.planner_status;
            }
            if candidate.planner_cost.is_none() {
                candidate.planner_cost = current.planner_cost;
            }
            if candidate.planner_tokens.is_none() {
                candidate.planner_tokens = current.planner_tokens;
            }
            if candidate.planner_provider.is_none() {
                candidate.planner_provider = current.planner_provider.clone();
            }

            candidate
        })
        .collect()
}

// Slice writers. All of these are reachable from `#[tauri::command]`s that
// the frontend calls while the app is live, so they are `async` and await the
// state gate fairly (see `lock_state_gate_blocking` for what the previous
// synchronous spin cost us).

pub async fn save_flights(flights: Vec<Flight>) -> Result<(), String> {
    update_state_async(move |state| {
        state.flights = merge_flights_for_frontend_save(&state.flights, flights);
    })
    .await
}

